const crypto = require('crypto');

/**
 * Encrypt the data with the key using AES and CBC mode.
 * The provided key bytes is long enough (>= 64 bytes). Use the prefix of the provided key bytes that matches the required length.
 * Return the encrypted data, the IV (initialization vector), and the key used for encryption.
 *
 * @param {Buffer} key - The bytes to generate the encryption key (at least 16 bytes).
 * @param {Buffer} data - The data to encrypt.
 * @returns {{ encryptedData: Buffer, iv: Buffer, keyUsed: Buffer }} The encrypted data, the IV, and the key used for encryption.
 */
function encrypt_data(key, data) {
  // AES-256 requires a 32-byte key (256 bits).
  // The docstring states the provided key is long enough (>= 64 bytes),
  // so we can safely take the first 32 bytes for AES-256.
  const AES_KEY_LENGTH = 32; // 256 bits
  // AES CBC mode requires a 16-byte IV (128 bits).
  const AES_IV_LENGTH = 16; // 128 bits

  // Use the prefix of the provided key bytes that matches the required length (32 bytes for AES-256).
  const keyUsed = key.slice(0, AES_KEY_LENGTH);

  // Generate a random Initialization Vector (IV) for CBC mode.
  // A unique, random IV is crucial for security in CBC mode.
  const iv = crypto.randomBytes(AES_IV_LENGTH);

  // Create a cipher using AES-256-CBC algorithm.
  // 'aes-256-cbc' specifies AES with a 256-bit key in CBC mode.
  const cipher = crypto.createCipheriv('aes-256-cbc', keyUsed, iv);

  // Encrypt the data.
  // The update method processes the data, and final method finishes the encryption,
  // including applying padding (PKCS7 by default for Node.js crypto).
  const encryptedData = Buffer.concat([cipher.update(data), cipher.final()]);

  // Return the encrypted data, the IV, and the key used for encryption.
  return { encryptedData, iv, keyUsed };
}
